// Map to CALKOWICIE osobny typ danych (nie "ulepszony obiekt"), z wlasnym
// zestawem metod (.get/.set/.has/.delete). Notacja nawiasowa ([]) jest
// mechanizmem specyficznym dla ZWYKLYCH obiektow, ktory na instancji Map
// probuje odczytac zwykla, publiczna wlasciwosc o nazwie "klucz" (ktorej
// Map nie ma), a nie wpis z wewnetrznej kolekcji par klucz-wartosc.

const slowa = ["kot", "pies", "kot", "ala", "kot"];
const licznik = new Map();

for (const s of slowa) {
  licznik.set(s, (licznik.get(s) || 0) + 1);
}

console.log(licznik); // -> Map(3) { "kot" => 3, "pies" => 1, "ala" => 1 }
console.log(licznik.get("kot")); // -> 3

const slowa = ["ala", "kot", "pies", "dom", "ptak"];
const grupy = new Map();

for (const s of slowa) {
  if (!grupy.has(s.length)) grupy.set(s.length, []);
  grupy.get(s.length).push(s);
}

console.log(grupy); // -> Map(3) { 3 => ["ala", "kot", "dom"], 4 => ["pies", "ptak"] }
console.log(grupy.get(4)); // -> ["pies", "ptak"]

