function stworzPamiec(fn) {
  const cache = new Map();
  return x => {
    if (!cache.has(x)) cache.set(x, fn(x));
    return cache.get(x);
  };
}

let wywolania = 0;
const kwadrat = stworzPamiec(x => {
  wywolania++;
  return x * x;
});

console.log(kwadrat(4), kwadrat(4), kwadrat(5)); // -> 16 16 25
console.log(wywolania);                          // -> 2

