class Slownik {
  #dane = new Map();

  dodaj(klucz, wartosc) {
    this.#dane.set(klucz, wartosc);
    return this;
  }

  pobierz(klucz) {
    return this.#dane.get(klucz);
  }

  usun(klucz) {
    return this.#dane.delete(klucz);
  }

  get ile() {
    return this.#dane.size;
  }
}

const s = new Slownik().dodaj("a", 1).dodaj("b", 2);
console.log(s.pobierz("a")); // -> 1
console.log(s.usun("a"));    // -> true
console.log(s.ile);          // -> 1

